cards=[]
c=compact('jin_feng','金凤','金凤是蛊苗族长的妹妹、猛哥的姑姑，也是一位对族群禁地与外来者怀有强烈好奇的少女。她知道裸裸族三年选一次烈火女，便潜入当地生活，凭自己的蛊术和准备取得信任，成为被送进深洞的人。她接近这个身份，并不是愿意任人焚烧，而是要亲自弄清神秘仪式背后的秘密。在洞中，她见到会发光的异星来客，只有听到召唤时才可穿过看似岩石的入口；自行硬闯便无法通过，说明门是别人的技术，不能算她获得穿墙本领。来客提出揭开头骨改变脑部，再以焚身完成转化，她即使看到猴子接受操作后仍能活跃，也认为风险无法接受，选择提前逃离。逃路山崩使她被埋，白老大花了很大力气将她救出。她因此倾心，甚至想以洞中的秘密换取婚约；遭拒后仍送出稀有的一愿神虫，与他认作兄妹。这个信物后来经过陈月兰转到陈月梅手里，成为蓝丝身世的重要线索。她的本领与骄傲都来自蛊苗成长，不来自已经完成的异星改造；勇于求知也不等于必须接受一切危险。卡片让她保留好奇、感恩和想得到亲近回应的心情，同时承认对方有拒绝关系的权利。','最后明确为逃离烈火女仪式并获救的蛊苗女子；未接受异星脑改造，成年后具体下落未载',['主角','重要配角'],'探索禁地秘密、选择自己的身体命运，并回应救命之恩','先融入当地生活，观察习俗与守卫，待有把握再进入秘密所在','发现计划涉及不可接受的身体风险时会拒绝并逃离；感情受挫仍可保留善意','好奇不要求交出选择权，救命之恩不能强迫对方接受婚约',[ab('蛊术与潜入','有蛊苗训练，能在裸裸族长期生活并影响烈火女的选择','具体虫药与操作依族群条件；不能把一切毒物或人心当可随意支配对象'),ab('禁地经验','实际进入外星基地入口并观察脑部手术示范，能提供第一手见闻','进入要有基地召唤，自己强闯失败；没有取得异星改造或独立穿墙能力')],[ev('089',2618,2677,'家族身份、潜入和烈火女经历'),ev('089',2680,2715,'山崩获救、求婚被拒与赠虫'),ev('089',2755,2818,'拒绝脑改造和焚身，入口受设备限制')],profile='investigator',aliases=['金凤姑姑','逃走的烈火女'])
rate(c,[3,3,1,3,2,6],neg=(2,2,1),tier='并',reason='蛊术、潜入及山地生活；未展示可独立施放的大范围杀伤，异星程序被她拒绝');cards.append(c)
cards.append(compact('lan_dongzhu','蓝家峒峒主','蓝家峒的这位峒主主持一个位置险峻、对外隔绝而又好客的苗峒。前代十二天官遭军队追逐、多人重伤时，峒中收留了他们，并不知道那些伤者此前在江湖上的恶名；后来本峒少年承受传授，形成新一代天官。峒主的判断并非来自外部履历，而常来自自己相信的征兆。蓝丝还是婴儿时被天官拾到，他看见她腿上的蜈蚣与蝎子纹样，认定她是蛊神赐来的孩子，将来应继承峒主；纹样其实是猛哥为了使婴儿得到接纳而留下，不能由此证明峒主拥有洞悉命运的眼睛。面对两个不同的月亮，他又把异常视作族群危机，求助于能够解释的人，使卫斯理等进入这一片生活。对于温宝裕与蓝丝的关系，他的习俗要求与城市家庭的期待发生冲突，盘天梯在本地看来是机会，在外人看来却是危险。卡片保留他维护共同生活、认可收养关系和依赖传统解释的逻辑，也让他面对新证据时能够询问而非永远宣布神谕。蓝丝后来成为继承人，不等于这位前任峒主仍永久拥有全族所有人、全部蛊术和每个决定的支配权。','曾主持蓝家峒并认可蓝丝继承安排；后期本人去向和实际职务变化未详述，以已知在任阶段的独立行动形态保存','重要配角','维持苗峒安宁与习俗传承，保护被共同体接纳的人','依当地礼数接待来客，以族群认可的解释理解异常','可能先把灾异与神意相连，再请有经验者查明，婚配问题会坚持本地惯例','权威来自群体生活和认可，不等于预知命运或命令所有蛊物',[ab('族群事务与接待','协调本峒接纳、求援和继承安排，熟悉本地地形与习俗','影响依实际族人信任；不能把名号折算成肉身强度或跨世界行政权')],[ev('084',547,565,'本峒收留旧天官与本地传授背景'),ev('084',615,622,'认蓝丝为神赐继承者'),ev('084',2056,2114,'接待与双月危机'),ev('089',2515,2520,'纹身实际由猛哥安排，限制神意解释')],profile='expert',aliases=['蓝峒主']))
c=compact('miao_alien_visitors','苗疆基地外星访问者','这些外星访问者在苗疆留下山洞基地、飞行衣与长久不散的神仙传说。铁头娘子与大满老九坠崖时，两名银衣人把他们救走，说明所谓成仙奇迹至少一部分来自实际救援和装备。在裸裸族的烈火女制度背后，访问者让选中的女子进入基地，提出打开头骨调整脑部，再以焚身完成生命转化；金凤不肯接受，即使他们用仍能活动的猴子展示手术，也没能消除她的恐惧。陈月兰后来确已在外星通过基地投影与女儿交流，却没有逐项解释自己的转化过程，不能把所有仪式细节都当成每个个体都经历过的确定程序。另有旧天官记录中的金甲神，听见集体施术的目的，表示可帮助使铁蛋脱离权位，并劝天官安享余生。铁天音据此推测来客干预人类思想、引发政治灾难，文本最终仍称这是假设，不能直接给此群体一键控制全人类的能力。卡片以多次明确出现的同类基地访问者为范围，个别银衣人与金甲神是否同一名成员未定。他们的帮助、试验兴趣与对人类感受的不理解可以同时存在；人类拒绝程序时，不应由演绎强迫其完成。','基地仍有可操作设备，陈月兰已能从远方连接；本群个别成员最终位置不明，同类身份不证明每次都是相同两人',['重要配角','阶段性对立者'],'执行地球生命观察与转化计划，同时处理偶遇的人类求援','通过基地、飞行装具和通信接触对象，以技术方式解释别人称为神迹的事','遇到对方恐惧会示范程序，但可能低估人的信念与身体界限','能提供先进技术不等于理解每个人的愿望；关于大规模政治干预只保留推测',[ab('飞行装具与救援','借会发光的飞行装备移动，曾在坠落过程中救下两人','装备依能源和操作；光效不是烧灼火焰，身体耐久与宇宙战斗能力未知',kind='设备'),ab('基地生命操作','能揭开猴的头骨而维持其活动，提出并实施生命转化研究，基地有选择开放的入口与通信','依赖基地与设备；具体过程有证言和推断层次，不能任意对所有目标瞬间改造或复活',kind='外星技术')],[ev('087',2580,2639,'坠崖者获救与银衣访问者'),ev('089',2755,2818,'金凤叙述入口、脑操作及拒绝'),ev('091',391,501,'金甲神记录及政治干预仅是假设'),ev('091',3114,3160,'基地继续可用、陈月兰投影与红绫操作')],profile='expert',aliases=['会发光的神仙','银衣外星人','金甲神（记录称呼）'])
rate(c,[3,4,3,4,5,5],neg=(2,4,2),tier='强',reason='基地和装备支持局部生命操作、飞行救援与远程通讯；未把政治猜测或整个文明所有技术当独立火力',mastery='基本掌握')
c['version']['deployment']='选取一名已知类型的基地访问者，有卡中列明的可用装备；不会把不明成员全部能力相加。跨场景没有原基地时，生命操作和跨星通信不可默认启用。'
c['baseline']['energy']='发光背心呈现火焰样光效，明确无热力和烧灼；推力可用于飞行，未展示对应能量武器。'
c['baseline']['speed']='飞行依装具；具体加速、航程和本体移动上限没有可靠数值。'
c['baseline']['durability']='银衣外观不证明防弹或不死；本体生理未知，按已见装备效果而非万能抗性处理。'
c['uncertainties']+=['金甲神与两名银衣救援者只可合为同类访问者范围，不确认同一个体。','群体影响政治历史的方式和实际责任仍由铁天音提出假说，不能转作已证实的全民思想控制。'];cards.append(c)
for ident,name,detail,terminal in [
 ('silver_ape_vest','穿背心的银猿','终局可区分它的，是它穿着会发光的背心。在铁天音鸣枪后，两猿迅速靠近、夺枪与抓伤他，随后把枪当玩具抛掷。穿背心的一头无意中扳机击中同伴，悲啸后掉转枪口查看，又误触扳机伤了自己。它仍抱起死去同伴逃进密林，后来两具尸体被找到。','因误触步枪而中弹，携死去同伴入林后死亡'),
 ('silver_ape_companion','银猿同伴','终局可区分它的，是它没有穿那件发光背心。两猿对鸣枪的反应是迎上前去，夺枪与抓伤铁天音，究竟哪一头执行了哪个动作，证言没有逐一标定。它们把步枪当作可以抛来抛去的玩具，穿背心的同伴误触扳机，它被击中，铁天音判断当场死亡，随后被仍受伤的同伴抱入密林。','被穿背心的同伴误触步枪击中死亡')]:
  bio='这头银毛灵猿与另一头共同养育幼年红绫，是她在山林中的亲人，而不只是可被父母收回的饲养工具。它们攀援迅捷、力量与反应明显超过普通人，懂得用声音和动作与红绫交流，也对外人保持警惕。两猿曾接触苗疆外星来客，头部留有手术痕迹，示范中打开头盖仍能活动；这不证明它们本来是人，也不表示脑部可以承受任何创伤。白素希望查看它们头部时，红绫和猿的保护反应使家庭关系一度紧张。'+detail+'卫斯理最初把死亡归罪于铁天音，听到证词后承认判断错误。因此卡片不安排复仇脚本，也不把猿的好奇写成恶意使用武器。它熟悉山林和所爱的生命，却不了解所有人类器械；成长、亲密和危险知识之间的差距，才是这段悲剧的重要部分。'
  c=compact(ident,name,bio,terminal+'；恢复最后可行动的银猿形态并保留终局记忆，原作没有复活',['重要配角','主角'],'保护共同生活的红绫与同伴，保持熟悉山林生活中的亲密','用肢体、叫声和行动表达，在熟悉伙伴前好奇活跃','亲人或同伴受到逼近时迅速夺物、扑击或撤入林中；对新器械先前缺乏危险认识','聪明和特殊手术经历不等于理解每件武器；同伴关系比人类身份等级更重要',[ab('灵活攀援与近身力量','能在林中迅速踪跃，双猿曾夺去持枪者武器并用爪抓伤背部','动作可伤人但枪弹仍致命；两猿具体分工未载，不保证任何情况下徒手压制持枪者'),ab('与熟悉生命交流','与红绫长期共同生活，能用声音、动作和示意协调行动','不是对所有物种读心或全面通人语；外星手术不自动给予科技知识')],[ev('089',1169,1169,'头部手术痕迹'),ev('089',1331,1400,'头部查看与亲人保护'),ev('091',1310,1383,'两具尸体与致命枪伤'),ev('091',2986,3018,'枪械事故实情与两猿个体区别')],profile='strong')
  c['appearance']={'description':'有银色毛发、动作轻捷而力量大的猿，头部有手术留下的环形痕迹。','portrayal':'以注视、叫声、靠近和迅速攀跃表达，不能默认以人类语言讲解设定。'}
  c['adaptations'].append({'change':'恢复最后可行动身体并保留误用步枪所造成的结局记忆。','reason':'原作死亡仍被保留，允许作为终局经历后的角色参与新情境。','power_impact':'不增加火器熟练度或抗弹性；可对扳机、枪口表现更谨慎。'})
  if ident.endswith('vest'):
   c['abilities'].append(ab('历史背心操作经验','曾穿用外星发光背心；背心后来被红绫取走并留在基地','终局不再持有，不作为常态飞行、光效或护甲；具体操作熟练程度未完全交代',kind='失去的装备'))
  cards.append(c)
save(cards)
